(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["oc"] = {"ui":{"skip":"Anar al contengut","back":"← Tornar a AI-gile","lang.button":"Lenga : {name}","lang.dialog":"Causís una lenga","lang.search":"Cercar de lengas","lang.none":"Cap de lenga correspond","lang.notYet":"{name} es pas encara traduch","theme.aria":"Cambiar entre tèma clar e escur","theme.toLight":"Passar al tèma clar","theme.toDark":"Passar al tèma escur","index.title":"AI-gile : ton equipa de dev IA, sus un sol tablèu","index.description":"AI-gile es un tablèu kanban per las equipas de còdi amb IA. Trabalhan mentre dormisses ; tu recebes una pichona pila de causas a decidir, ensajar e acceptar.","hero.logoAlt":"Icòna del tablèu AI-gile","hero.h1.html":"Ton equipa de dev IA, sus un sol&nbsp;tablèu.","hero.alpha":"🐣 Pre-alfa barrada","hero.alphaTitle":"Precòç e pas acabat : mercé d'ensajar !","hero.lede":"Bastisson mentre dormisses. Te desrevelhas amb una pichona pila : unas question, unas causas a ensajar, un diamant violet o doas. Clica, accèpta, e tòrna a ton café.","dl.windows":"Aplicacion Windows","dl.browser":"Lançar dins lo navegador","dl.soon":"Lèu disponible","dl.notify":"🔔 Avisatz-me quand dobrirà","dl.notifySmall":"Alfa o beta","hero.secondary":"Agile, mas l'equipa a pas jamai besonh d'un café en pè. (Fan de stand-ups tot parièr.)","pitch.h2":"AI-gile en tant de mots coma vòles","pitch.lede":"Causís una longor, d'un mot a 144. Cada longor es una descripcion pròpria, escricha per aquela talha. Tira lo cursor o utiliza las sagetas.","pitch.rangeLabel":"Longor en mots","pitch.dice":"🎲 una autra version","pitch.words.one":"{n} mot","pitch.words.other":"{n} mots","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letras","pitch.chars.one":"{n} caractèr","pitch.chars.other":"{n} caractèrs","count.line.html.one":"{n} carta sul tablèu en aquesta ora","count.line.html.other":"{n} cartas sul tablèu en aquesta ora","features.aria":"Çò que fa","f.pile.h":"Una pila sonque per tu","f.pile.html":"<b>Per tu</b> recampa tot çò que te espèra, dins totes los projèctes : question, causas a ensajar, tascas que sonque un uman pòt far. Ta fila ditz çò qu'es lo seguent e quant de temps pren.","f.sleep.h":"Equipas que trabalhan mentre dormisses","f.sleep.p":"Cada projècte a un cap e una equipa d'agents IA. Comenta una carta e l'equipa se desrevelha, fa lo trabalh e lo te torna amb d'etapas que un uman cansat pòt seguir.","f.tester.h":"Un tèster IA verifica primièr","f.tester.p":"Abans que res te tòque, un tèster seguís las etapas dins una còpia de l'aplicacion e mòstra çò qu'a vist, amb una captura d'ecran. Percor los reüssits e accèpta en un clic.","f.proof.h":"De pròvas, pas de prometenças","f.proof.p":"Cada liurason mòstra çò qu'a cambiat : los fichièrs, lo diff, las capturas d'ecran. Cap de besonh de dobrir cada aplicacion per saber s'es acabat.","f.chat.h":"Charra amb tos caps","f.chat.p":"Una barra a l'estil Discord : una icòna per projècte, de diamants violets per çò que te cal. Manda una idèa a un cap ; la càmbia en cartas e en plan, amb un boton ✅ Go.","f.tidy.h":"Se ten ordenat tot sol","f.tidy.p":"Las cartas parentas se fondon en una, los títols embolhats son corregits, e una verificacion dels tokens manten lo còdi leugièr. Mens de causas entre las qualas cambiar, mens de qué pensar.","f.private.h":"Teu, sus ton ordenador","f.private.li1":"Lo tablèu fonciona sus ta pròpria maquina e respond pas qu'a tu.","f.private.li2":"Los DMs privats entre personas son chifrats de cap a cap.","f.private.li3":"Cap de compte, cap de traçaire, cap de cookie.","f.lang.h":"Dins ta lenga","f.lang.p":"Mai de 120 lengas, del neerlandés, del galés e del japonés al pirata, a Yoda e al klingon, amb un cambiament rapid cap a l'anglés per los mots de desvolopaire.","tl.aria":"Cronologia, de la primièra convèrsa a la fuèlha de rota","tl.h2":"De la primièra charra a çò que ven","tl.lede":"Datas e oras vertadièras, dins ton fus orari. Aprèp uèi es lo plan, sens cap de data prometuda.","tl.today":"Uèi","tl.planned":"previst","tl.cards.one":"{n} carta","tl.cards.other":"{n} cartas","join.h2":"Rejonh-nos","join.lede":"AI-gile es bastit per un uman pichon e un fum d'agents pacients. Per ara es privat, en alfa barrada amb d'amics. Vòles ensajar quand dobrirà ?","join.btn":"Marcar mon interès","join.small":"T'escriurem per corrièl, pas mai","footer.tag":"AI-gile. Cap de traçaire, cap de cookie, cap de café en pè.","footer.licence":"Licéncia professionala","footer.status":"Estat","form.sending":"Mandadís…","form.failed":"Aquò a pas foncionat : tòrna ensajar mai tard.","form.offline":"Pas pogut joindre AI-gile : tòrna ensajar mai tard.","interest.title":"AI-gile : avisa-me quand l'alfa dobrirà","interest.description":"Daissa ton corrièl per saber quora l'alfa o la beta barrada d'AI-gile dobrirà.","interest.h1":"🔔 Avisa-me quand dobrirà","interest.lede":"AI-gile es en pre-alfa barrada. Daissa ton corrièl e t'escriurem un còp, quand i aurà una plaça per tu.","interest.email":"Ton corrièl","interest.which":"Quin ensag ?","interest.alpha":"Alfa barrada : precòça, brusca, amb fòrça cambiaments","interest.beta":"Beta : mai establa, mai tard","interest.both":"L'un o l'autre, çò que vendrà primièr","interest.submit":"Met-me sus la lista","interest.thanks":"Mercé ! Ès sus la lista.","licence.title":"AI-gile : licéncia professionala","licence.description":"Utilizas AI-gile dins ton ofici ? Demanda una licéncia professionala gratuita.","licence.h1":"📜 Licéncia professionala","licence.lede":"Utilizas AI-gile al trabalh ? Digas-nos qual siás e çò que fas. Se fa un pauc de ben, la licéncia es gratuita.","licence.company":"Entrepresa","licence.website":"Site web","licence.what":"Çò que fas","licence.how":"Cossí aquò ajuda lo monde","licence.email":"Corrièl","licence.submit":"Demandar","licence.thanks":"Mercé ! Te respondrem per corrièl.","status.title":"Estat d'AI-gile","status.h1":"Estat d'AI-gile","status.quiet":"Tot es tranquil","status.checking":"Verificacion…","status.offline":"Pòdi pas joindre lo servici d'estat ara (tornarai ensajar)","status.updated":"mes a jorn {ago}","status.justNow":"ara meteis","status.min":"i a {n} min","status.hours":"i a {n} h","status.days":"i a {n} j","live.h2":"Agacha-lo se bastir, en dirècte","live.caption":"Cada carta es amagada : vezes la forma del trabalh, pas las paraulas.","live.watching.one":"en dirècte : {n} agacha","live.watching.other":"en dirècte : {n} agachan","live.offline":"Lo tablèu en dirècte pren un pauc d'alen. Torna d'aquí un moment.","live.cols":"Backlog|A far|En cors|Verificacion de l'equipa|Per tu de testar|Per l'equipa|Fach","live.last.now":"Darrièra carta desplaçada pas qu'ara","live.last.min.one":"Darrièra carta desplaçada fa {n} min","live.last.min.other":"Darrièra carta desplaçada fa {n} min","live.last.hour.one":"Darrièra carta desplaçada fa {n} ora","live.last.hour.other":"Darrièra carta desplaçada fa {n} oras","live.last.day.one":"Darrièra carta desplaçada fa {n} jorn","live.last.day.other":"Darrièra carta desplaçada fa {n} jorns"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robòts.","Delegat."]},{"n":2,"texts":["Kanban robotic.","Agents, ordenats.","Idèas, bastidas."]},{"n":3,"texts":["Kanban per robòts.","Las idèas venon foncions.","Kanban d'agents gratuit."]},{"n":5,"texts":["Tablèu kanban menat per d'agents.","Escrives de cartas. Los agents bastisson.","Gratuit, local, ensajat, un pauc fòl."]},{"n":8,"texts":["Un kanban gratuit ont trabalhan d'agents IA.","Escriu una idèa. Los agents la bastisson. Accèptas.","Agile per un uman e fòrça robòts paciënts."]},{"n":13,"texts":["Un tablèu kanban sus ton ordenador ont d'agents IA prenon las cartas.","Escriu una idèa. Una equipa d'agents la bastís. Un tèster la verifica.","Gratuit, cap de compte, cap de traçaire : un tablèu, de robòts e tu al comande."]},{"n":21,"texts":["AI-gile es un tablèu kanban per trabalhar amb d'agents de còdi IA. Prenon las cartas ; tu las ensajas e las accèptas.","Cada projècte a un cap e una equipa d'agents IA. Comenta quina carta que siá e l'equipa se met a trabalhar.","Un tablèu personal e gratuit que fonciona sus ton ordenador. Los trabalhaires son de robòts. Cel que ditz òc, es tu."]},{"n":34,"texts":["Possas d'idèas sus un tablèu. Una equipa d'agents IA las càmbia en foncions que fonciònan, las ensaja e te las torna amb d'etapas per ensajar. Res compta coma acabat tant que ne diguèsses pas òc.","AI-gile es un tablèu kanban fach a l'ostal que Rich a bastit amb fòrça ajuda dels agents que ara maneja. Es gratuit, fonciona sus ton ordenador, e es partejat amb d'amics, pas vendut.","Imagina un tablèu kanban ordinari, amb de colomnas del Backlog a Fach, levat que las cartas las prenon d'agents IA. Raportan lor avançament, pausan de question quand blocan, e esperan totjorn ton aprovacion."]},{"n":55,"texts":["AI-gile es un tablèu kanban ont l'equipa es facha d'agents IA. Cada projècte a un cap que planifica lo trabalh e d'ajudaires que lo bastisson. Quand una foncion es prèsta, un tèster IA l'ensaja e pren una captura d'ecran, puèi arriba dins ta pila. Accèpta-la, o comenta e la tornan trabalhar.","Tot a començat coma la manièra d'una persona de seguir fòrça sessions de còdi IA a l'encòp, puèi es venguda un vertadièr tablèu. Fonciona sus ta maquina, demanda pas de compte e a pas cap de traçaire. Es gratuit per los amics e los curioses. Es tanben pas acabat, doncas espèra-te a d'arèstas e a una susprèsa de còps que i a.","Siaguem sinceres. Te cal totjorn aver las idèas, e te cal totjorn verificar los resultats. Çò que fa AI-gile, es tot çò d'entremièg : ten las cartas en òrdre, desrevelha l'agent bon quand comentas, mòstra exactament çò qu'a cambiat, e met tot aquò dins una pichona pila per tu."]},{"n":89,"texts":["AI-gile es un tablèu kanban gratuit que fas foncionar sus ton pròpri ordenador. Al lòc de personas, cada projècte a una equipa d'agents IA : un cap que càmbia tas idèas en cartas e en plan, e d'ajudaires que prenon las cartas per òrdre de prioritat. Quand quicòm es bastit, un tèster IA seguís las etapas de tèst e te mòstra çò qu'a vist. Puèi aquò espèra dins una sola pila marcada Per tu. L'accèptas, o comentas e l'equipa ensaja un còp mai. Res arriba jamai a Fach sens tu.","Qualques foncions que t'espèras benlèu pas. Un gach de la nuèch manten la colomna A far garnida mentre dormisses, en causissent de cartas que demandan cap de responsa de ta part. Un comptaire de tokens mòstra quant los agents an utilizat uèi e aquesta setmana, e lo Mòde Sens Tokens lor ditz d'arrestar de despendre. Pòdes escriure a d'amics, e los messatges privats son chifrats de cap a cap. Lo tablèu parla a l'entorn de 120 lengas, e mai lo neerlandés, lo flamenc, lo pirata e lo klingon. Res d'aquò còsta un ciment, e degun ensaja pas de t'o vendre.","AI-gile es un pichon projècte personal, pas una entrepresa. Rich voliá s'ocupar de mantun projècte de còdi IA sens dobrir cada aplicacion per anar veire, doncas el e los agents an bastit un tablèu per aquò, puèi an emplegat lo tablèu per bastir lo rèsta de se meteis. Es en pre-alfa barrada, çò que vòl dire que fonciona, mai que mai, per un punhat d'amics. I a pas de pagina de tarifas, pas de letra d'informacion e pas de plan de creissença. Se te sembla util, pòdes demandar d'ensajar quand dobrirà un pauc mai."]},{"n":144,"texts":["AI-gile es un tablèu kanban per un uman e fòrça agents IA. Fonciona sus ton pròpri ordenador e es completament gratuit. Apondes de projèctes, e cada projècte recep un cap e una pichona equipa. Charras amb lo cap, un pauc coma sus Discord, e descrives una idèa ; lo cap la càmbia en cartas e en plan, puèi espèra qu'aprimes Go. L'equipa trabalha las cartas per òrdre de prioritat, amb una linha de comanda simpla facha per los modèls de lenga. Abans que res te torne, un tèster IA seguís las etapas dins una còpia de l'aplicacion e ligà una captura d'ecran. Lo trabalh acabat arriba dins ta pila amb los fichièrs cambiats e lo diff. L'accèptas, o daisses un comentari e l'equipa se desrevelha e ensaja tornar. Sonque tu pòdes mudar una carta cap a Fach.","Una jornada amb AI-gile, a pauc près. Al ser daisses qualques comentaris : aqueste boton es al mal endreit, aquela lista deuriá èsser triada, poiriam aver un mòde escur. Vas te jaire. Los agents legisson los comentaris, fan los cambiaments, los ensajan e te los tornan. Se A far se voida, lo gach de la nuèch lo torna emplir amb de cartas del backlog que demandan cap de responsa de ta part. Al matin i a una pichona pila : unas question e unas causas d'ensajar, caduna amb d'etapas qu'una persona ensomiada pòt seguir e una captura d'ecran de la causa que fonciona. Percorres tot, accèptas çò qu'es bon e tornas lo rèsta. Un comptaire de tokens mòstra çò qu'aquò tot a consumit, e lo Mòde Sens Tokens es aquí per las setmanas magras. Puèi dejunas, e per aquò los agents pòdon pas encara ajudar.","Primièr, çò qu'AI-gile es pas. Es pas una startup, es pas en venda e degun recampa pas tas donadas. Es un tablèu gratuit que fonciona sus ton ordenador, sens compte, sens traçaire e sens cookie. Çò qu'es : un sol lòc ordenat per veire a l'encòp totes tos projèctes de còdi IA, amb una equipa d'agents que fa las cartas e tu que prenes las decisions. Fonda las cartas parentas, corregís los títols embolhats, e gaita que lo còdi demòre leugièr. Parla a l'entorn de 120 lengas, del neerlandés e del flamenc al pirata e al klingon. Los amics se pòdon escriure, en privat e chifrat. Es estat bastit per Rich e un fum d'agents paciënts, en s'utilizant quasi totjorn el meteis. Es en pre-alfa barrada, doncas es brut en qualques endreits. Se te sembla amusant, demanda gentilament e benlèu entraràs mai lèu."]}],"quips":{"1":"Un mot. Agardit. Benlèu tròp agardit.","3":"Tres mots. Ja mai sincèr que la màger part de las paginas de produch.","8":"Uèch mots. Encara mai cort qu'un stand-up.","21":"Las longors son de story points, çaquelà. Òc ben, evidentament.","55":"Cinquanta-cinc mots. Doas cartas se son acabadas mentre legissiás aquò.","144":"Aquò es la longa. I a pas de 233. Los agents son anats se jaire."}},"timeline":{"first-idea.name":"La primièra idèa","first-idea.line":"La tota primièra convèrsa, abans que i aguèsse un sol bocin de còdi.","first-board.name":"Primièr tablèu","first-board.line":"Un tablèu que seguís sa pròpria bastison : cartas, colomnas, tirar e daissar, projèctes.","team-roles.name":"Equipa e ròtles","team-roles.line":"Perfils d'agents, modèls d'equipa, espacis e qual fa qué.","install.name":"Installacion e versions","install.line":"Un zip qu'un amic pòt installar, mesas a jorn automaticas, canals e tornada en arrièr.","usage-saver.name":"Estalvi d'utilizacion","usage-saver.line":"Mesurar çò que còstan las execucions, tenir lo còdi leugièr, estalviar ton limit.","friends.name":"Amics e partiment","friends.line":"DMs privats, un relai embolhat, convits, ròtles e projèctes partejats.","languages.name":"Lengas","languages.line":"Cada tèxte d'ecran dins un fichièr de lenga, amb lo neerlandés e lo flamenc d'en primièr.","ai-tester.name":"Tèster IA","ai-tester.line":"Un tèster verifica cada liurason primièr e mòstra çò qu'a vist.","website.name":"Lo site web","website.line":"aigile.lol, la pagina de presentacion e aquesta cronologia.","streaming.name":"Charra e difusion","streaming.line":"Discord, Twitch, OBS, mòde streamer, GIFs e emojis.","no-ai.name":"Edicion sens IA","no-ai.line":"Un tablèu per las gents que programan sens IA, e de tablèus publics.","night-watch.name":"Gach de la nuèch","night-watch.line":"Un gach e Scrum Master mantenon las equipas en tasca mentre dormisses.","p-more.name":"Tot lo rèsta","p-more.line":"D'idèas mai pichonas que son encara a esperar son torn.","p-android.name":"Telefòn e Android","p-android.line":"Accedir a ton tablèu dempuèi un telefòn, puèi una aplicacion Android nativa.","p-release.name":"Alfa e al-delà","p-release.line":"Alfa barrada, lo site en linha, puèi la beta.","p-languages.name":"Mai de lengas","p-languages.line":"Mai de cent lengas, e un mòde d'immersion per los aprenents.","p-engines.name":"Mai de motors IA","p-engines.line":"Causís Claude, Codex o Gemini per cada agent.","p-pro.name":"Practica professionala","p-pro.line":"Etiquetas de risc, barrièras de fusion, cartas d'incident e garda-fòlzes.","p-self.name":"Se ocupar de tu","p-self.line":"Mòde cansat, rampèls de suenh de se e 4:20.","p-servers.name":"Servidors e escala","p-servers.line":"Paramètres globals de servidor, ròtles e planificacion de la creissença.","p-livestream.name":"Extras de difusion","p-livestream.line":"Charra Twitch, emojis personalizats e una vista publica en dirècte."},"words":{"button":"📖 Mots de desvolopaire","h":"📖 Mots de desvolopaire explicats","intro":"Los mots que los desvolopaires (e las equipas IA) emplegan, en lenga simpla.","search":"Cercar un mot…","none":"Cap de mot correspond.","close":"Barrar","list":[{"id":"backlog","word":"Backlog","text":"Idèas e trabalh pas encara planificats. Res i es pas trabalhat tant que passa pas dins A far."},{"id":"sprint","word":"Sprint","text":"Un cort moment de trabalh (sovent una o doas setmanas) amb un ensemble de cartas convengut d'acabar.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"Un punt rapid : çò que cada membre a fach, çò que farà après, e çò que lo bloca.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Quicòm que marcha pas coma deuriá.","also":["bugs"]},{"id":"test","word":"Test","text":"Ensajar un trabalh acabat per verificar que fa çò qu'es estat demandat, abans de l'acceptar.","also":["tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Un instantanèu enregistrat del còde, amb una pichona nòta de çò que a cambiat. Pòdes totjorn tornar a un.","also":["commits"]},{"id":"push","word":"Push","text":"Mandar los instantanèus enregistrats (commits) d'aqueste ordenador cap a GitHub, per que sián salvats e partejats."},{"id":"branch","word":"Branch","text":"Una linha de trabalh a part dins lo còde, per poder cambiar de causas sens tocar la version principala.","also":["branches"]},{"id":"merge","word":"Merge","text":"Tornar ajustar los cambiaments d'una branch dins la version principala."},{"id":"repo","word":"Repo","text":"Lo dossièr del projècte amb lo còde e tot l'istoric dels commits, sovent tanben gardat sus GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"Rengar lo còde sens cambiar çò que fa : fichièrs mai pichons, noms mai clars, mens de repeticions."},{"id":"deploy","word":"Deploy","text":"Metre una version novèla en linha, per exemple sus un servidor ont lo monde l'utiliza."},{"id":"kanban","word":"Kanban","text":"Un tablèu amb de colomnas (A far, En cors, Fach) ont las cartas van d'esquèrra a drecha a mesura que lo trabalh avança."},{"id":"wip","word":"Limita WIP","text":"Work in progress : lo maximum de cartas qu'una colomna deu tenir, per que l'equipa acabe las causas abans d'en començar mai.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Demandar que los cambiaments d'una branch sián verificats e fusionats dins la version principala.","also":["PR"]},{"id":"hook","word":"Hook","text":"Una pichona comanda que s'executa tota sola a un moment definit, ex. quand una session IA comença, per que l'equipa ausisca tos comentaris.","also":["hooks"]},{"id":"token","word":"Token","text":"L'unitat en qual l'utilizacion de l'IA es comptada : a pauc près qualques letras de tèxte legit o escrich. Mens de tokens, mai d'ofèrta que demòra.","also":["tokens"]},{"id":"agent","word":"Agent","text":"Una IA que trabalha tota sola sus una tasca : legís lo còde, fa de cambiaments, executa de verificacions, e te torna dire.","also":["agents"]}]}};
